CREATE TABLE event_communities (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, host_id TEXT NOT NULL REFERENCES avatar_users(id), title TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE event_community_rooms (room_id TEXT PRIMARY KEY REFERENCES event_rooms(id), community_id TEXT NOT NULL REFERENCES event_communities(id));
CREATE TABLE event_conversation_members (kind TEXT NOT NULL CHECK(kind IN ('room','community')), scope_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES avatar_users(id), joined_at TEXT NOT NULL, left_at TEXT, removed_at TEXT, mode TEXT NOT NULL DEFAULT 'quiet' CHECK(mode IN ('quiet','open')), muted INTEGER NOT NULL DEFAULT 0 CHECK(muted IN (0,1)), revision INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(kind,scope_id,user_id));
CREATE TABLE event_group_messages (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN ('room','community')), scope_id TEXT NOT NULL, sender_id TEXT NOT NULL REFERENCES avatar_users(id), sender_name TEXT NOT NULL, text TEXT NOT NULL CHECK(length(text) BETWEEN 1 AND 1000), reply_id TEXT REFERENCES event_group_messages(id), created_at TEXT NOT NULL, hidden_at TEXT);
CREATE INDEX event_group_scope ON event_group_messages(kind,scope_id,seq);
CREATE TABLE event_group_receipts (message_id TEXT NOT NULL REFERENCES event_group_messages(id), viewer_id TEXT NOT NULL REFERENCES avatar_users(id), delivered_at TEXT NOT NULL, read_at TEXT, PRIMARY KEY(message_id,viewer_id));
CREATE TABLE event_community_greetings (pair_id TEXT PRIMARY KEY REFERENCES event_social_pairs(id), community_id TEXT NOT NULL REFERENCES event_communities(id), greeting_id TEXT NOT NULL);
